/* tcc_link.c - WindyFilm build check (WindyStrife): link a module with the camera's own TCC loader object, as ML's
 * module.c loads it on the camera, and report the image size. Link only: no module code runs.
 *
 *   tcc_new; tcc_set_options("-nostdlib"); tcc_add_symbol(each core symbol); tcc_add_file(module);
 *   size = tcc_relocate(s, NULL); buf = size bytes; tcc_relocate(s, buf); __module_info_<name> checked.
 *
 * The core symbols come from tcc_syms.c, generated by build.sh: one dummy object per symbol the module imports that is
 * listed in the camera's card .sym (a symbol missing there is not added, so TCC fails with "undefined symbol").
 *
 * build: arm-linux-gnueabi-gcc -O2 -marm -march=armv5te -static -fno-builtin tcc_link.c tcc_syms.c <libtccx.o> -lm
 * run:   qemu-arm-static ./tcc_link MODULE.mo  ->  "[tcc] linked: image N bytes" and "[tcc] module_info ... OK" */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/mman.h>

typedef struct TCCState TCCState;
TCCState *tcc_new(void);
void tcc_delete(TCCState *s);
int tcc_set_options(TCCState *s, const char *str);
int tcc_add_file(TCCState *s, const char *filename);
int tcc_add_symbol(TCCState *s, const char *name, const void *val);
int tcc_relocate(TCCState *s1, void *ptr);
void *tcc_get_symbol(TCCState *s, const char *name);

/* what libtccx.o expects from the camera core (ML src/tcc-glue.c, mem.c) */
int _tcc_open(const char *p, int flags) { (void)flags; return open(p, O_RDONLY); }
int _tcc_read(int fd, void *buf, int size) { return (int)read(fd, buf, size); }
int _tcc_close(int fd) { return close(fd); }
int _tcc_lseek(int fd, int off, int whence) { return (int)lseek(fd, off, whence); }
void _tcc_exit(int code) { fprintf(stderr, "[tcc] exit(%d)\n", code); exit(code); }
void *__mem_malloc(size_t n, unsigned flags, const char *file, unsigned line) { (void)flags; (void)file; (void)line; return malloc(n); }
void __mem_free(void *p) { free(p); }

struct core_sym { const char *name; const void *addr; };
extern const struct core_sym wf_core_syms[];   /* tcc_syms.c */

struct module_info { unsigned char magic, major, minor, patch; const char *name, *long_name; void *init, *deinit; };

int main(int argc, char **argv)
{
    if (argc < 3) {
        fprintf(stderr, "usage: tcc_link MODULE.mo MODNAME\n");
        return 2;
    }
    TCCState *s = tcc_new();
    tcc_set_options(s, "-nostdlib");
    int n = 0;
    for (; wf_core_syms[n].name; n++)
        tcc_add_symbol(s, wf_core_syms[n].name, wf_core_syms[n].addr);
    fprintf(stderr, "[tcc] %d core symbols added\n", n);
    if (tcc_add_file(s, argv[1]) < 0) {
        fprintf(stderr, "[tcc] tcc_add_file failed\n");
        return 1;
    }
    int size = tcc_relocate(s, NULL);
    if (size < 0) {
        fprintf(stderr, "[tcc] tcc_relocate(NULL) failed: the camera would say 'Linking failed'\n");
        return 1;
    }
    void *buf = mmap(0, size, PROT_READ | PROT_WRITE | PROT_EXEC, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (buf == MAP_FAILED || tcc_relocate(s, buf) < 0) {
        fprintf(stderr, "[tcc] tcc_relocate(buf) failed\n");
        return 1;
    }
    printf("[tcc] linked: image %d bytes\n", size);
    char nm[80];
    snprintf(nm, sizeof nm, "__module_info_%s", argv[2]);
    const struct module_info *mi = tcc_get_symbol(s, nm);
    if (!mi) {
        printf("[tcc] %s not found\n", nm);
        return 1;
    }
    int ok = mi->magic == 0x5A && mi->major == 8 && mi->minor <= 0 && mi->init && mi->deinit;
    printf("[tcc] %s: magic 0x%02x api %d.%d.%d name '%s' -> %s\n", nm, mi->magic, mi->major, mi->minor, mi->patch,
           mi->name ? mi->name : "?", ok ? "OK" : "REJECTED");
    static const char *const tbl[] = { "__module_strings_", "__module_cbr_", "__module_config_", "__module_prophandlers_" };
    for (int i = 0; i < 4; i++) {
        snprintf(nm, sizeof nm, "%s%s", tbl[i], argv[2]);
        printf("[tcc] %-34s %s\n", nm, tcc_get_symbol(s, nm) ? "present" : "-");
    }
    snprintf(nm, sizeof nm, "__module_strings_%s", argv[2]);
    const char *const *str = tcc_get_symbol(s, nm);
    for (int i = 0; str && str[i] && i < 32; i += 2)
        printf("[tcc] string %s = %s\n", str[i], str[i + 1] ? str[i + 1] : "-");
    tcc_delete(s);
    return ok ? 0 : 1;
}
